// Minimal hash table with separate chaining
class HashMap {
  #buckets;
  #size = 0;
  #capacity;
  static LOAD_FACTOR = 0.75;

  constructor(capacity = 16) {
    this.#capacity = capacity;
    this.#buckets  = Array.from({ length: capacity }, () => []);
  }

  // Simple polynomial hash — good enough for illustration
  #hash(key) {
    let h = 0;
    for (let i = 0; i < key.length; i++)
      h = (h * 31 + key.charCodeAt(i)) >>> 0; // keep 32-bit positive
    return h % this.#capacity;
  }

  set(key, value) {                            // O(1) avg
    const idx   = this.#hash(key);
    const chain = this.#buckets[idx];
    const entry = chain.find(e => e[0] === key);
    if (entry) { entry[1] = value; return; }   // update existing
    chain.push([key, value]);
    this.#size++;
    if (this.#size / this.#capacity > HashMap.LOAD_FACTOR) this.#rehash();
  }

  get(key) {                                   // O(1) avg
    const chain = this.#buckets[this.#hash(key)];
    return chain.find(e => e[0] === key)?.[1];
  }

  delete(key) {                                // O(1) avg
    const idx   = this.#hash(key);
    const chain = this.#buckets[idx];
    const i     = chain.findIndex(e => e[0] === key);
    if (i === -1) return false;
    chain.splice(i, 1);
    this.#size--;
    return true;
  }

  #rehash() {                                  // O(n) — rare
    this.#capacity *= 2;
    const old = this.#buckets;
    this.#buckets = Array.from({ length: this.#capacity }, () => []);
    this.#size = 0;
    for (const chain of old)
      for (const [k, v] of chain) this.set(k, v);
  }

  get size() { return this.#size; }
}

const map = new HashMap();
map.set('alice', 30);
map.set('bob',   25);
map.set('alice', 31);           // update
console.log(map.get('alice')); // 31
console.log(map.get('carol')); // undefined
map.delete('bob');
console.log(map.size);          // 1

// Big-O summary — Hash Table
//
// Operation    | Average | Worst (all keys collide)
// -------------|---------|-------------------------
// get(key)     | O(1)    | O(n)
// set(key, v)  | O(1)*   | O(n)
// delete(key)  | O(1)    | O(n)
// rehash       | —       | O(n)  (rare, amortised O(1))
//
// * amortised — occasional rehash is O(n)

// Practical note: JS built-in Map vs Object
// Map  — arbitrary key types, guaranteed insertion-order iteration, no prototype pollution
// {}   — string/symbol keys, slight overhead from prototype chain, marginally faster for integer-keyed property bags

// Common interview patterns using a Map for O(1) lookups:
// 1. Two-sum
function twoSum(nums, target) {
  const seen = new Map();
  for (let i = 0; i < nums.length; i++) {
    const complement = target - nums[i];
    if (seen.has(complement)) return [seen.get(complement), i];
    seen.set(nums[i], i);
  }
  return [];
}
console.log(twoSum([2, 7, 11, 15], 9)); // [0, 1]

// 2. Frequency counter
function mostFrequent(arr) {
  const freq = new Map();
  for (const x of arr) freq.set(x, (freq.get(x) ?? 0) + 1);
  return [...freq.entries()].reduce((a, b) => b[1] > a[1] ? b : a)[0];
}
console.log(mostFrequent([1, 2, 2, 3, 3, 3])); // 3
